nya putra-putri Anda.\n\nUntuk pendidikan terbaik putra-putri Anda, ingat satu nama: Labschool.\n\n#LabschoolCibubur #SDLabschoolCibubur #PSBLabschoolCibubur&quot;,&quot;media_type&quot;:&quot;VIDEO&quot;,&quot;permalink&quot;:&quot;https:\/\/www.instagram.com\/reel\/DcsGhdpSBLc\/&quot;,&quot;timestamp&quot;:&quot;2026-08-31T03:21:26+0000&quot;,&quot;username&quot;:&quot;labschoolcibubur.official&quot;,&quot;thumbnail_url&quot;:&quot;https:\/\/scontent-sin6-3.cdninstagram.com\/v\/t51.82787-15\/789554178_18129773129495203_1056942678176470904_n.jpg?stp=dst-jpg_e35_tt6&amp;_nc_cat=106&amp;ccb=7-5&amp;_nc_sid=18de74&amp;efg=eyJlZmdfdGFnIjoiQ0xJUFMuYmVzdF9pbWFnZV91cmxnZW4uQzMifQ%3D%3D&amp;_nc_ohc=MsNESji_luYQ7kNvwHN9C61&amp;_nc_oc=Ado61s4twuSXHTr0BAuA2vEvMx_oe6rSqHUMVXhlfjBKyQD4r_MdEl5D9y1lcm-u67o&amp;_nc_zt=23&amp;_nc_ht=scontent-sin6-3.cdninstagram.com&amp;edm=ANo9K5cEAAAA&amp;_nc_gid=Zy9Wi4uXYlhVaITsvHKMgQ&amp;_nc_tpa=Q5bMBQKiBL7tX4gtpgOQPG1fPyF1n0WCShESAQ1a-5O-u0Ey9bkkwSsborBqPE8fxfm5Y9TJU82EeGRC2w&amp;oh=00_AQKQTAZe38Dq8af42Uf_p0TpgTaxVzyfmWAwKm_8J8CDWg&amp;oe=6AA8039C&quot;,&quot;comments_count&quot;:4,&quot;like_count&quot;:316,&quot;account_type&quot;:&quot;personal&quot;,&quot;profile_picture_url&quot;:&quot;https:\/\/scontent-sin6-2.cdninstagram.com\/v\/t51.2885-19\/488563044_3185409138276553_5523912058816762332_n.jpg?stp=dst-jpg_s206x206_tt6&amp;_nc_cat=109&amp;ccb=7-5&amp;_nc_sid=bf7eb4&amp;efg=eyJ2ZW5jb2RlX3RhZyI6InByb2ZpbGVfcGljLnd3dy41OTEuQzMifQ%3D%3D&amp;_nc_ohc=9pQckrDqnV8Q7kNvwFaUkgl&amp;_nc_oc=Ado9C68KCIXdyJVP_MojP28Z1EolhfPoRUdRHJGCF42E59Rsx077qPeOslAJZ-m1zKg&amp;_nc_zt=24&amp;_nc_ht=scontent-sin6-2.cdninstagram.com&amp;edm=AP4hL3IEAAAA&amp;_nc_tpa=Q5bMBQKa3YzgfpXegTDImRVA1MC6uFhbJhGShqf9s6-d6jdPW7bUbbEhmdZ6Z30O31mR8NFVK2DZ97CUTg&amp;oh=00_AQIX9wNT7eVwgnk_6zbykIYDHpnDRayLbF5GSG6y1vDANw&amp;oe=6AA8148D&quot;,&quot;show_likes_count&quot;:&quot;true&quot;,&quot;show_comments_count&quot;:&quot;true&quot;,&quot;popup_follow_button&quot;:&quot;yes&quot;,&qu