restasi setinggi-tingginya! \ud83c\udf0c\u2728\n\n#LabschoolCibubur #SMALabschoolCibubur #osn2026&quot;,&quot;media_type&quot;:&quot;IMAGE&quot;,&quot;media_url&quot;:&quot;https:\/\/scontent-sin11-1.cdninstagram.com\/v\/t51.82787-15\/777778473_18128163968495203_8327163366335178746_n.jpg?stp=dst-jpg_e35_tt6&amp;_nc_cat=104&amp;ccb=7-5&amp;_nc_sid=18de74&amp;efg=eyJlZmdfdGFnIjoiRkVFRC5iZXN0X2ltYWdlX3VybGdlbi5DMyJ9&amp;_nc_ohc=byZ5W-FJEF8Q7kNvwEb03bM&amp;_nc_oc=AdoMQPdkQUmIn6jW_XJFdm8Bmr_OIi9Jgcb__mn13MuxO6wfDT3oxKOvKzENLyi4ej0&amp;_nc_zt=23&amp;_nc_ht=scontent-sin11-1.cdninstagram.com&amp;edm=ANo9K5cEAAAA&amp;_nc_gid=Zy9Wi4uXYlhVaITsvHKMgQ&amp;_nc_tpa=Q5bMBQLxnqTDdcvHv7gYRvlozgdRJwJ3ps2qw3h7XMm-_K3WK_XY1HRauBAndPpLJS10S8aYn5yooQwoZg&amp;oh=00_AQK_Fx-hX8EFO6nQk1hzq-lBTW6OCp1GEM0g_RCzNBtoMQ&amp;oe=6AA802D6&quot;,&quot;permalink&quot;:&quot;https:\/\/www.instagram.com\/p\/DcPRdHISL9w\/&quot;,&quot;timestamp&quot;:&quot;2026-08-19T22:35:31+0000&quot;,&quot;username&quot;:&quot;labschoolcibubur.official&quot;,&quot;comments_count&quot;:0,&quot;like_count&quot;:418,&quot;account_type&quot;:&quot;personal&quot;,&quot;profile_picture_url&quot;:&quot;https:\/\/scontent-sin6-2.cdninstagram.com\/v\/t51.2885-19\/488563044_3185409138276553_5523912058816762332_n.jpg?stp=dst-jpg_s206x206_tt6&amp;_nc_cat=109&amp;ccb=7-5&amp;_nc_sid=bf7eb4&amp;efg=eyJ2ZW5jb2RlX3RhZyI6InByb2ZpbGVfcGljLnd3dy41OTEuQzMifQ%3D%3D&amp;_nc_ohc=9pQckrDqnV8Q7kNvwFaUkgl&amp;_nc_oc=Ado9C68KCIXdyJVP_MojP28Z1EolhfPoRUdRHJGCF42E59Rsx077qPeOslAJZ-m1zKg&amp;_nc_zt=24&amp;_nc_ht=scontent-sin6-2.cdninstagram.com&amp;edm=AP4hL3IEAAAA&amp;_nc_tpa=Q5bMBQKa3YzgfpXegTDImRVA1MC6uFhbJhGShqf9s6-d6jdPW7bUbbEhmdZ6Z30O31mR8NFVK2DZ97CUTg&amp;oh=00_AQIX9wNT7eVwgnk_6zbykIYDHpnDRayLbF5GSG6y1vDANw&amp;oe=6AA8148D&quot;,&quot;show_likes_count&quot;:&quot;true&quot;,&quot;show_comments_count&quot;:&quot;true&quot;,&quot;popup_follow_button&quot;:&quot;yes&quot;,&quot;popup_follow_button_text&quot;:&quot;Follow&quot;}" data-media-type="I