<script>
$(document).ready(function(){

  function updateInput(role){
    if(role === 'student' || role === 'parent'){
      $("#labelIdentity").text("NIS");
      $("#identityInput")
        .attr("type", "text")
        .attr("name", "nis")
        .attr("placeholder", "Masukkan NIS")
        .val("");
    } else if(role === 'teacher' || role === 'staff'){
      $("#labelIdentity").text("Email");
      $("#identityInput")
        .attr("type", "email")
        .attr("name", "email")
        .attr("placeholder", "Masukkan email Microsoft")
        .val("");
    } else {
      $("#labelIdentity").text("NPP");
      $("#identityInput")
        .attr("type", "text")
        .attr("name", "npp")
        .attr("placeholder", "Masukkan NPP")
        .val("");
    }
  }

  // trigger saat berubah
  $("#roleSelect").on("change", function(){
    updateInput($(this).val());
  });

  // trigger awal (default selected)
  updateInput($("#roleSelect").val());


  $("#formForget").submit(function(){
    $("#btnSubmit .text").text("Processing...");
    $("#btnSubmit .spinner-border").removeClass("d-none");
    $("#btnSubmit").prop("disabled", true);
  });
});
</script>

</body>
